            check(t.motion.durationFast, 0.15, "prism: motion.durationFast")
            check(t.motion.durationSlow, 0.35, "prism: motion.durationSlow")
            check(t.motion.durationSlower, 0.5, "prism: motion.durationSlower")
            check(t.motion.presentationCrossfade, false, "prism: motion.presentationCrossfade")
            check(t.motion.springBouncy, DSSpringToken(duration: 0.5, bounce: 0.3, blendDuration: 0, settle: 0.818, mass: 1, stiffness: 157.9137, damping: 17.5929), "prism: motion.springBouncy")
            check(t.motion.springSheet, DSSpringToken(duration: 0.3, bounce: 0.2, blendDuration: 0, settle: 0.404, mass: 1, stiffness: 438.6491, damping: 33.5103), "prism: motion.springSheet")
            check(t.motion.springSmooth, DSSpringToken(duration: 0.4, bounce: 0, blendDuration: 0, settle: 0.587, mass: 1, stiffness: 246.7401, damping: 31.4159), "prism: motion.springSmooth")
            check(t.motion.springSnappy, DSSpringToken(duration: 0.35, bounce: 0.15, blendDuration: 0, settle: 0.487, mass: 1, stiffness: 322.2728, damping: 30.5183), "prism: motion.springSnappy")
            check(t.components.button.motionPress, DSSpringToken(duration: 0.35, bounce: 0.15, blendDuration: 0, settle: 0.487, mass: 1, stiffness: 322.2728, damping: 30.5183), "prism: components.button.motionPress")
        }
        do {
            let t = DSTokenSet(DSTokenContext(brand: .prism, motion: .reduced))
