            check(t.motion.durationFast, 0.1, "prism motion=reduced: motion.durationFast")
            check(t.motion.durationSlow, 0.15, "prism motion=reduced: motion.durationSlow")
            check(t.motion.durationSlower, 0.15, "prism motion=reduced: motion.durationSlower")
            check(t.motion.presentationCrossfade, true, "prism motion=reduced: motion.presentationCrossfade")
            check(t.motion.springBouncy, DSSpringToken(duration: 0.3, bounce: 0, blendDuration: 0, settle: 0.44, mass: 1, stiffness: 438.6491, damping: 41.8879), "prism motion=reduced: motion.springBouncy")
            check(t.motion.springSheet, DSSpringToken(duration: 0.25, bounce: 0, blendDuration: 0, settle: 0.367, mass: 1, stiffness: 631.6547, damping: 50.2655), "prism motion=reduced: motion.springSheet")
            check(t.motion.springSmooth, DSSpringToken(duration: 0.3, bounce: 0, blendDuration: 0, settle: 0.44, mass: 1, stiffness: 438.6491, damping: 41.8879), "prism motion=reduced: motion.springSmooth")
            check(t.motion.springSnappy, DSSpringToken(duration: 0.25, bounce: 0, blendDuration: 0, settle: 0.367, mass: 1, stiffness: 631.6547, damping: 50.2655), "prism motion=reduced: motion.springSnappy")
            check(t.components.button.motionPress, DSSpringToken(duration: 0.25, bounce: 0, blendDuration: 0, settle: 0.367, mass: 1, stiffness: 631.6547, damping: 50.2655), "prism motion=reduced: components.button.motionPress")
        }
    }

