        check(DSColorToken.accent.appearances(.prism), DSColorAppearances(any: DSRGBA(.displayP3, 0.9011, 0.5979, 0.3306, 1), dark: DSRGBA(.displayP3, 0.9011, 0.5979, 0.3306, 1), highContrast: DSRGBA(.displayP3, 0.9011, 0.5979, 0.3306, 1), darkHighContrast: DSRGBA(.displayP3, 0.9011, 0.5979, 0.3306, 1), watch: DSRGBA(.displayP3, 0.9011, 0.5979, 0.3306, 1)), "prism: color-accent")
