    @Test func prismNativeColors() {
        do {
            let t = DSTokenSet(DSTokenContext(brand: .prismNative))
            check(DSColor(brand: .prismNative, transparency: .standard).accent, Color("prism/color-accent", bundle: DSTokensBundle.bundle), "prism-native: color.accent")
            check(DSColor(brand: .prismNative, transparency: .standard).accentGlow, Color("prism/color-accent-glow", bundle: DSTokensBundle.bundle), "prism-native: color.accentGlow")
            check(DSColor(brand: .prismNative, transparency: .standard).accentPressed, Color("prism/color-accent-pressed", bundle: DSTokensBundle.bundle), "prism-native: color.accentPressed")
            check(DSColor(brand: .prismNative, transparency: .standard).accentSubtle, Color("prism/color-accent-subtle", bundle: DSTokensBundle.bundle), "prism-native: color.accentSubtle")
            check(DSColor(brand: .prismNative, transparency: .standard).bgFillAccent, Color("prism/color-bg-fill-accent", bundle: DSTokensBundle.bundle), "prism-native: color.bgFillAccent")
            check(DSColor(brand: .prismNative, transparency: .standard).bgFillAccentStrong, Color("prism/color-bg-fill-accent-strong", bundle: DSTokensBundle.bundle), "prism-native: color.bgFillAccentStrong")
            check(DSColor(brand: .prismNative, transparency: .standard).bgFillCritical, Color("prism/color-bg-fill-critical", bundle: DSTokensBundle.bundle), "prism-native: color.bgFillCritical")
            check(DSColor(brand: .prismNative, transparency: .standard).bgFillInverse, Color("prism/color-bg-fill-inverse", bundle: DSTokensBundle.bundle), "prism-native: color.bgFillInverse")
            check(DSColor(brand: .prismNative, transparency: .standard).bgFillNeutralSubtle, Color("prism/color-bg-fill-neutral-subtle", bundle: DSTokensBundle.bundle), "prism-native: color.bgFillNeutralSubtle")
            check(DSColor(brand: .prismNative, transparency: .standard).bgPage, Color("prism/color-bg-page", bundle: DSTokensBundle.bundle), "prism-native: color.bgPage")
            check(DSColor(brand: .prismNative, transparency: .standard).bgSurface, Color("prism/color-bg-surface", bundle: DSTokensBundle.bundle), "prism-native: color.bgSurface")
            check(DSColor(brand: .prismNative, transparency: .standard).bgSurfaceNested, Color("prism/color-bg-surface-nested", bundle: DSTokensBundle.bundle), "prism-native: color.bgSurfaceNested")
            check(DSColor(brand: .prismNative, transparency: .standard).bgSurfaceOverlay, Color("prism/color-bg-surface-overlay", bundle: DSTokensBundle.bundle), "prism-native: color.bgSurfaceOverlay")
            check(DSColor(brand: .prismNative, transparency: .standard).bgSurfaceRaised, Color("prism/color-bg-surface-raised", bundle: DSTokensBundle.bundle), "prism-native: color.bgSurfaceRaised")
            check(DSColor(brand: .prismNative, transparency: .standard).bgTintAccent, Color("prism/color-bg-tint-accent", bundle: DSTokensBundle.bundle), "prism-native: color.bgTintAccent")
            check(DSColor(brand: .prismNative, transparency: .standard).bgTintCritical, Color("prism/color-bg-tint-critical", bundle: DSTokensBundle.bundle), "prism-native: color.bgTintCritical")
            check(DSColor(brand: .prismNative, transparency: .standard).bgTintInfo, Color("prism/color-bg-tint-info", bundle: DSTokensBundle.bundle), "prism-native: color.bgTintInfo")
