    @Test func springCurves() {
        checkSpring(DSTokenSet(DSTokenContext(brand: .prism)).motion.springBouncy, [(0.0818, 0.3187), (0.2045, 0.8867), (0.409, 1.0372), (0.6135, 0.9999), (0.818, 0.999)], "prism: motion.springBouncy (0.5, 0.3)")
